    // summary whatever the check said. The check's satisfied flag is passed
    // into the summary payload as a planned reference, never computed on.
    if (checkNumber >= maxChecks) {
      return check.pipe(
        Node.andThen((result) =>
          Summarize.call({
            passed: result.satisfied,
            totalChecks: checkNumber,
            finalStatus: result.status
          })
        )
      )
    }
    return check.pipe(
      Node.branch({
        if: (result) => result.satisfied,
        then: (result) =>
          Summarize.call({
            passed: true,
            totalChecks: checkNumber,
            finalStatus: result.status
          }),
        else: (result) =>
          Sleep.action.call({ millis: 5_000 }).pipe(
            Node.andThen(() =>
              Gate.to({
                condition,
                checkCmd,
                checkNumber: checkNumber + 1,
                maxChecks,
                lastStatus: result.status
              })
            )
          )
      })
    )
