  Summarize.toLayer(({ finalStatus, passed, totalChecks }) =>
    Effect.succeed({
      passed,
      totalChecks,
      finalStatus,
      summary: passed
        ? `Gate passed after ${totalChecks} check(s)`
        : `Gate timed out after ${totalChecks} check(s). Last status: ${finalStatus}`
    })
  ),
  Sleep.layer
)

const GateLayer = Layer.mergeAll(
  implementations,
  Interpreter.layer(Gate)
).pipe(
  Layer.provideMerge(Action.layerImplementations),
  Layer.provideMerge(FlowEngine.layerMemory),
  Layer.provideMerge(NodeCrypto.layer)
)

export const main: Effect.Effect<typeof GateResult.Type> = Gate.execute(
  {
    condition: "CI is green",
    checkCmd: "gh run list --limit 1",
    checkNumber: 1,
    maxChecks: 30,
    lastStatus: "not yet checked"
  },
