 *
 * Smithers shape: the zod showcase. Extract Task with nested object/array/
 * enum schemas and `.min(0).max(1)` bounds, validate Task consuming it via
 * `deps`, then a computed forward Task (a render-prop returning an object).
 *
 * flows shape: a straight three-step chain. The zod schemas become effect
 * Schema structs; `.min(0).max(1)` becomes `Schema.Number.check(
 * Schema.isBetween(0, 1))`, `z.enum` becomes `Schema.Literals`, optional
 * fields become `Schema.optional`, and `z.record(z.string(), z.string())`
 * becomes `Schema.Record`. The computed forward step becomes a sealed action
 * whose implementation does the filtering and Object.fromEntries work,
 * because it computes on the validate step's result.
 *
 * Deviations:
 * - Agents (extractor, validator) are STUBs (GAPS.md GAP-1); nothing pushes
 *   these schemas into the model request (GAPS.md GAP-2).
 */
import * as NodeCrypto from "@effect/platform-node/NodeCrypto"
import { FlowEngine } from "@smthrs/engine"
import { Action, Flow, Interpreter } from "@smthrs/flow"
import { Node } from "@smthrs/plan"
import * as Effect from "effect/Effect"
import * as Layer from "effect/Layer"
import * as Schema from "effect/Schema"

const EntityType = Schema.Literals([
  "person",
  "company",
  "product",
  "event",
  "document",
  "other"
])

// zod: z.number().min(0).max(1)
const Confidence = Schema.Number.check(Schema.isBetween({ minimum: 0, maximum: 1 }))

const ExtractedField = Schema.Struct({
  key: Schema.String,
  value: Schema.String,
  confidence: Confidence
})

// zod: extractedSchema
const Extracted = Schema.Struct({
  entityName: Schema.String,
  entityType: EntityType,
  fields: Schema.Array(ExtractedField),
  rawSnippets: Schema.Array(Schema.String),
  summary: Schema.String
})

const ValidatedField = Schema.Struct({
  key: Schema.String,
  value: Schema.String,
  confidence: Confidence,
  valid: Schema.Boolean,
  correctedValue: Schema.optional(Schema.String)
})

// zod: validatedSchema
const Validated = Schema.Struct({
  entityName: Schema.String,
  entityType: EntityType,
  fields: Schema.Array(ValidatedField),
  overallConfidence: Confidence,
  issues: Schema.Array(Schema.String),
  summary: Schema.String
})

// zod: forwardSchema
const Forwarded = Schema.Struct({
  entityName: Schema.String,
  entityType: EntityType,
  structuredOutput: Schema.Record(Schema.String, Schema.String),
  overallConfidence: Confidence,
  nextStep: Schema.String,
  summary: Schema.String
})

/** smithers: extract Task, extractorAgent with {read, bash, grep}. */
export const Extract = Action.make("typed-extractor/extract", {
  payload: {
    rawInput: Schema.String,
    filePaths: Schema.Array(Schema.String),
    targetSchema: Schema.String
  },
  success: Extracted
})

/** smithers: validate Task, deps={{ extract }}. */
export const Validate = Action.make("typed-extractor/validate", {
  payload: {
    entityName: Schema.String,
    entityType: EntityType,
    fields: Schema.Array(ExtractedField),
    rawSnippets: Schema.Array(Schema.String)
  },
  success: Validated
})

/**
 * smithers: the computed forward Task. Its render-prop body filtered and
 * re-keyed the validated fields; that computation moves into this action's
 * implementation because plan code may pass step results but not compute on
 * them.
 */
export const Forward = Action.make("typed-extractor/forward", {
  payload: {
    validated: Validated,
    nextStep: Schema.String
  },
  success: Forwarded
})

export const TypedExtractorStage = Flow.make("typed-extractor/stage", {
  payload: {
    rawInput: Schema.String,
    filePaths: Schema.Array(Schema.String),
    targetSchema: Schema.String,
    nextStep: Schema.String
  },
  success: Forwarded,
  body: ({ filePaths, nextStep, rawInput, targetSchema }) =>
    Extract.call({ rawInput, filePaths, targetSchema }).pipe(
      Node.andThen((extracted) =>
        Validate.call({
          entityName: extracted.entityName,
          entityType: extracted.entityType,
          fields: extracted.fields,
          rawSnippets: extracted.rawSnippets
        })
      ),
      Node.andThen((validated) => Forward.call({ validated, nextStep }))
    )
})

/** STUB agent seam (GAPS.md GAP-1) plus the real computed forward step. */
const implementations = Layer.mergeAll(
  Extract.toLayer(({ rawInput }) =>
    Effect.succeed({
      entityName: "Acme Robotics",
      entityType: "company" as const,
      fields: [
        { key: "employees", value: "120", confidence: 0.9 },
        { key: "industry", value: "robotics", confidence: 0.7 }
      ],
      rawSnippets: [rawInput.slice(0, 80)],
      summary: "Extracted a company entity."
    })
  ),
  Validate.toLayer(({ entityName, entityType, fields }) =>
    Effect.succeed({
      entityName,
      entityType,
      fields: fields.map((field) => ({
        ...field,
        valid: field.confidence >= 0.5,
        ...(field.confidence < 0.9 ? { correctedValue: field.value.trim() } : {})
      })),
      overallConfidence: 0.8,
      issues: [],
      summary: "All fields validated."
    })
  ),
  Forward.toLayer(({ nextStep, validated }) =>
    Effect.succeed({
      entityName: validated.entityName,
      entityType: validated.entityType,
      structuredOutput: Object.fromEntries(
        validated.fields
          .filter((field) => field.valid)
          .map((field) => [field.key, field.correctedValue ?? field.value])
      ),
      overallConfidence: validated.overallConfidence,
      nextStep,
      summary: validated.summary
    })
  )
)

const StageLayer = Layer.mergeAll(
  implementations,
  Interpreter.layer(TypedExtractorStage)
).pipe(
  Layer.provideMerge(Action.layerImplementations),
  Layer.provideMerge(FlowEngine.layerMemory),
  Layer.provideMerge(NodeCrypto.layer)
)

export const main: Effect.Effect<typeof Forwarded.Type> = TypedExtractorStage.execute(
  {
    rawInput: "Acme Robotics is a 120-person robotics company evaluating orchestrators.",
    filePaths: [],
    targetSchema: "auto-detect",
    nextStep: "downstream-processor"
  },
  { executionId: "typed-extractor-1" }
).pipe(
  Effect.orDie,
  Effect.provide(StageLayer)
)
"}]}
{"messages":[{"role":"system","content":"<CHEATSHEET_V0>"},{"role":"user","content":"I want to expose a small research workflow as a reusable, callable capability another agent can invoke as a tool, not just inline logic. Define a research-topic flow that returns a one-line summary for a topic, run it as a durable child flow from a parent workflow, and also publish it as a named, described tool binding, with typed input and output schemas, that a model-facing agent harness can call directly. The parent flow should call the child and then compose a final answer from the child's summary."},{"role":"assistant","content":"/**
 * Port of examples/workflow-tool.tsx.
 *
 * Smithers shape: `workflowTool({ name, description, workflow })` wraps a
 * child workflow as a callable agent tool; an OpenAIAgent gets it in its
 * `tools` map and the parent workflow's Task runs that agent.
 *
 * flows shape: two halves.
 * 1. Durable composition: the child research flow is an ordinary `Flow.make`,
 *    and the parent's body invokes it with `.child(...)`, which runs it as a
 *    durable child boundary (its own execution, its own journal), which is
 *    what `workflowTool` promised ("a durable child run").
 * 2. Model-facing tool: `FlowBinding.make` from @smthrs/harness is the
 *    current way to expose a flow-shaped capability to an agent. The binding
 *    carries the input/output schemas (projected to JSON Schema in ctx.flows)
 *    and a handler; `FlowBinding.source` groups bindings into the `flows`
 *    option the agent host accepts.
 *
 * Deviations:
 * - The agent that CALLS the tool cannot be declared in the flow DSL; the
 *   answer step is a STUB action (GAPS.md GAP-1). The binding is real and
 *   typechecks, but wiring it to a live agent happens at the composition
 *   root (the AgentAction host flows option), not here.
 * - smithers passes the workflow itself to workflowTool; FlowBinding takes a
 *   handler, so the binding's handler re-enters the flow via its own execute
 *   path in a real composition (GAPS.md GAP-8).
 */
import * as NodeCrypto from "@effect/platform-node/NodeCrypto"
import { FlowEngine } from "@smthrs/engine"
import { Action, Flow, Interpreter } from "@smthrs/flow"
import * as FlowBinding from "@smthrs/harness/FlowBinding"
import { Node } from "@smthrs/plan"
import * as Effect from "effect/Effect"
import * as Layer from "effect/Layer"
import * as Schema from "effect/Schema"

const ResearchInput = Schema.Struct({ topic: Schema.String })
const ResearchOutput = Schema.Struct({ summary: Schema.String })
const Answer = Schema.Struct({ answer: Schema.String })

/**
 * smithers: researchWorkflow — a one-Task workflow whose Task body is a
 * computed object literal. The literal computes only on payload, which is
 * real data at plan time, so here it is plain `Node.succeed`.
 */
export const ResearchTopic = Flow.make("workflow-tool/research-topic", {
  payload: ResearchInput.fields,
  success: ResearchOutput,
  body: ({ topic }) =>
    Node.succeed({
      summary: `${topic} can be composed as a durable child run.`
    })
})

/** smithers: the answer Task run by the OpenAIAgent. STUB agent seam. */
export const ComposeAnswer = Action.make("workflow-tool/answer", {
  payload: { topic: Schema.String, summary: Schema.String },
  success: Answer
})

/**
 * smithers: the outer workflow. `.child` (not `.call`) so the research flow
 * runs as its own durable execution, matching workflowTool's child-run
 * semantics; `.call` would splice its plan inline instead.
 */
export const AgentCallsWorkflow = Flow.make("workflow-tool/agent-calls-workflow", {
  payload: { topic: Schema.String },
  success: Answer,
  body: ({ topic }) =>
    ResearchTopic.child({ topic }).pipe(
      Node.andThen((research) =>
        ComposeAnswer.call({ topic, summary: research.summary })
      )
    )
})

/**
 * smithers: workflowTool({ name: "research_topic", ... }). The binding is
 * what an agent sees in ctx.flows: name, description, and both schemas as
 * JSON Schema documents. Passed to an agent run via
 * `AgentAction.layerHost({ flows: [researchTools], ... })`.
 */
export const researchTopicBinding = FlowBinding.make({
  flow: {
    name: "research_topic",
    description: "Run the durable research workflow for a topic.",
    input: ResearchInput,
    output: ResearchOutput,
    capabilities: [],
    effects: undefined
  },
  handler: ({ topic }) =>
    Effect.succeed({
      summary: `${topic} can be composed as a durable child run.`
    })
})

export const researchTools = FlowBinding.source("workflow-tool", [
  researchTopicBinding
])

const implementations = ComposeAnswer.toLayer(({ summary, topic }) =>
  Effect.succeed({ answer: `On ${topic}: ${summary}` })
)

const WorkflowToolLayer = Layer.mergeAll(
  implementations,
  Interpreter.layer(AgentCallsWorkflow),
  Interpreter.layer(ResearchTopic)
).pipe(
  Layer.provideMerge(Action.layerImplementations),
  Layer.provideMerge(FlowEngine.layerMemory),
  Layer.provideMerge(NodeCrypto.layer)
)

export const main: Effect.Effect<typeof Answer.Type> = AgentCallsWorkflow.execute(
  { topic: "durable workflows" },
  { executionId: "workflow-tool-1" }
).pipe(
  Effect.orDie,
  Effect.provide(WorkflowToolLayer)
)
"}]}
{"messages":[{"role":"system","content":"<CHEATSHEET_V0>"},{"role":"user","content":"For a flows run that has a human-approval gate in it, I want a lightweight status probe: fold the run's event stream into a simple view model with a status of starting, waiting-approval, or finished, a running count of events seen, and the latest output text from the gated node. It does not need a real UI or dashboard, just a pure reducer over the AgentEvent stream, where permission-required or suspended events mean waiting, turn-closed means finished, and transition-applied carries the output text, plus a stream-fold helper that runs it to completion."},{"role":"assistant","content":"/**
 * Port of examples/ui/e2e-approval-probe.tsx.
 *
 * Smithers shape: a real React dashboard mounted with
 * `createGatewayReactRoot`, subscribing to a live run through
 * `useGatewayRunEvents(runId)` and `useGatewayNodeOutput({runId, nodeId})`,
 * deriving a status ("starting" | "waiting-approval" | "finished") and
 * rendering it.
 *
 * flows: THERE IS NO EQUIVALENT SURFACE. flows has no gateway server, no
 * React bindings, no per-node output subscription, and no way for a workflow
 * author to attach a UI to a flow (GAPS.md GAP-7). This file is a PARTIAL
 * port: it is honest about what exists today, which is the framework-neutral
 * `Stream<AgentEvent>` a harness run emits ("A caller renders it, journals
 * it, or ignores it" — packages/smithers/agent/harness/src/AgentEvent.ts). The
 * probe's view-model derivation is ported onto that stream; the React mount,
 * the gateway transport, and the node-output query are not portable.
 *
 * What is ported:
 * - runIdFromUrl -> caller-supplied run id (no gateway URL scheme exists).
 * - useGatewayRunEvents -> folding Stream<AgentEvent> into a ProbeView.
 * - the status derivation -> AgentEvent tags: PermissionRequired/Suspended
 *   mark waiting, TurnClosed marks finished.
 * - useGatewayNodeOutput -> the CellSettled/TransitionApplied output text,
 *   the closest thing to a node's output the event stream carries.
 */
import * as AgentEvent from "@smthrs/harness/AgentEvent"
import * as Effect from "effect/Effect"
import * as Stream from "effect/Stream"

export type ProbeStatus = "starting" | "waiting-approval" | "finished"

/** The smithers component's derived state, as plain data instead of JSX. */
export interface ProbeView {
  readonly runId: string
  readonly status: ProbeStatus
  readonly eventCount: number
  readonly marker: string
}

export const initialView = (runId: string): ProbeView => ({
  runId,
  status: "starting",
  eventCount: 0,
  marker: ""
})

/**
 * One reduction step: what each gateway hook contributed, read off the
 * event stream instead.
 */
export const reduce = (view: ProbeView, event: AgentEvent.AgentEvent): ProbeView => {
  const eventCount = view.eventCount + 1
  switch (event._tag) {
    // The gated task parking is what the probe rendered as waiting-approval.
    case "permission-required":
    case "suspended":
      return { ...view, eventCount, status: "waiting-approval" }
    // The run's terminal event: the probe's "finished".
    case "turn-closed":
      return { ...view, eventCount, status: "finished" }
    // The nearest analogue of useGatewayNodeOutput: the settled turn's
    // output text rides the transition.
    case "transition-applied":
      return event.transition._tag === "complete"
        ? { ...view, eventCount, marker: event.transition.output }
        : { ...view, eventCount }
    default:
      return { ...view, eventCount }
  }
}

/**
 * The whole probe as a stream fold: give it the Stream<AgentEvent> a
 * agent host records or replays and it answers
 * with the final view the React component would have rendered.
 */
export const probe = (
  runId: string,
  events: Stream.Stream<AgentEvent.AgentEvent>
): Effect.Effect<ProbeView> => Stream.runFold(events, () => initialView(runId), reduce)
